            default         => throw new \InvalidArgumentException("Unknown icon: {$name}"),
        };

        if ($attrs === []) {
            return $svg;
        }

        $extra = '';
        foreach ($attrs as $key => $value) {
            $extra .= ' ' . $key . '="' . htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '"';
        }

        // Inject after <svg, before any existing attributes.
        // Note: if the SVG already defines an attribute you pass here, the browser
        // will use the first occurrence — i.e. the injected value takes precedence.
        return '<svg' . $extra . substr($svg, 4);
    }

    /**
     * Returns a sort-direction indicator SVG for a table column header.
     * Replaces the identical $sortIcon closure previously duplicated in every index template.
     *
     * Usage: <?= \Luster\Core\View::sortIcon('name', $sort, $dir) ?>
     *
     * @param string $col  The column key this indicator is for.
     * @param string $sort The currently active sort column.
     * @param string $dir  The current sort direction ('asc' or 'desc').
     */
    public static function sortIcon(string $col, string $sort, string $dir): string
    {
        if ($sort !== $col) {
            return '<svg viewBox="0 0 10 14" width="9" height="9" fill="currentColor" style="opacity:.35;flex-shrink:0"><path d="M5 0l3 4H2zM5 14l-3-4h6z"/></svg>';
        }
        if ($dir === 'asc') {
            return '<svg viewBox="0 0 10 14" width="9" height="9" fill="currentColor" style="flex-shrink:0"><path d="M5 0l3 4H2z"/><path d="M5 14l-3-4h6z" fill-opacity=".25"/></svg>';
        }
        return '<svg viewBox="0 0 10 14" width="9" height="9" fill="currentColor" style="flex-shrink:0"><path d="M5 0l3 4H2z" fill-opacity=".25"/><path d="M5 14l-3-4h6z"/></svg>';
    }

    // -----------------------------------------------------------------------
    // Public rendering (fan-facing PHP modular templates)
    // -----------------------------------------------------------------------

    /**
     * Renders a public content fragment wrapped in templates/default/layout.php.
     *
     * If layout.php does not exist, returns the fragment alone. This means
     * embed mode works before the site owner creates layout.php.
     *
     * @param string $template  Filename only, e.g. 'join.php' or 'members.php'
     * @param array  $data      Variables available in the content template and layout.
     */
    public function renderPublic(string $template, array $data = []): string
    {
        $content    = $this->renderFragment($template, $data);
        $layoutPath = rtrim($this->templateDir, '/\\')
                    . DIRECTORY_SEPARATOR . 'default'
                    . DIRECTORY_SEPARATOR . 'layout.php';

        if (!is_file($layoutPath)) {
            return $content;
        }

        return $this->renderPhp($layoutPath, array_merge($data, ['content' => $content]));
    }

    /**
     * Renders a public content fragment only — no layout.php wrapping.
     *
     * Used by the embed entry points (public/embed/*.php) where the site
     * owner's own page provides the outer HTML.
     *
     * @param string $template  Filename only, e.g. 'join.php'
     * @param array  $data      Variables available in the content template.
     */
    public function renderFragment(string $template, array $data = []): string
    {
        $path = rtrim($this->templateDir, '/\\')
              . DIRECTORY_SEPARATOR . 'default'
              . DIRECTORY_SEPARATOR . $template;

        if (!is_file($path)) {
            throw new RuntimeException("Public template not found: {$path}");
        }

        return $this->renderPhp($path, $data) . self::attribution();
    }

    /**
     * Returns the "Powered by Luster" attribution line appended to every embed fragment.
     * Standalone embed files that do not go through renderFragment() append this manually.
     */
    public static function attribution(): string
    {
        return "\n" . '<p class="fl-powered-by">Powered by <a href="https://luster.starceress.net/" rel="nofollow">Luster</a></p>';
    }

    // -----------------------------------------------------------------------
    // Internals
    // -----------------------------------------------------------------------

    private function renderPhp(string $path, array $data): string
    {
        // Merge shared vars (set once via share()) with per-render data.
        // $data values take precedence over shared values.
        extract(array_merge($this->shared, $data), EXTR_SKIP);

        ob_start();

        try {
            require $path;
        } catch (\Throwable $e) {
            ob_end_clean();
            throw $e;
        }

        return (string) ob_get_clean();
    }

    private function substituteTokens(string $content, array $data): string
    {
        // Process loop blocks first: {loop_key}...{/loop_key}
        $content = preg_replace_callback(
            '/\{([a-z_][a-z0-9_]*)\}(.*?)\{\/\1\}/si',
            function (array $m) use ($data): string {
                $key   = $m[1];
                $block = $m[2];

                if (!isset($data[$key]) || !is_array($data[$key])) {
                    return '';
                }

                $output = '';

                foreach ($data[$key] as $item) {
                    if (!is_array($item)) {
                        continue;
                    }

                    $output .= $this->substituteTokens($block, $item);
                }

                return $output;
            },
            $content
        ) ?? $content;

        // Substitute tokens — ViewRaw values are inserted verbatim (pre-escaped
        // server-side HTML); all other scalar values are htmlspecialchars()-escaped.
        foreach ($data as $key => $value) {
            if ($value instanceof ViewRaw) {
                $content = str_replace('{' . $key . '}', $value->html, $content);
                continue;
            }

            if (!is_scalar($value) && $value !== null) {
                continue;
            }

            $escaped = htmlspecialchars(
                (string) ($value ?? ''),
                ENT_QUOTES | ENT_SUBSTITUTE,
                'UTF-8'
            );

            $content = str_replace('{' . $key . '}', $escaped, $content);
        }

        return $content;
    }
}
